        int intSum = Integer.parseInt(first) + Integer.parseInt(second);
        double doubleSum = Double.parseDouble(first) + Double.parseDouble(second);
        System.out.println("Int sum: " + intSum);
        System.out.println("Double sum: " + doubleSum);

        Integer x = Integer.valueOf(1000);
        Integer y = Integer.valueOf(1000);
        System.out.println("1000 == 1000: " + (x == y));
        System.out.println("1000 equals 1000: " + x.equals(y));
