import java.util.ArrayList;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        List<Integer> ids = new ArrayList<>();
        ids.add(40);
        ids.add(10);
        ids.add(30);
        ids.add(20);
        ids.add(0, 99);
        System.out.println(ids);

        int removed = ids.remove(1);
        System.out.println("Removed at index 1: " + removed);
        ids.remove(Integer.valueOf(30));
        System.out.println(ids);

        System.out.println("Contains 10: " + ids.contains(10));
        System.out.println("Index of 20: " + ids.indexOf(20));
        System.out.println("Index of 30: " + ids.indexOf(30));

        List<String> names = new ArrayList<>();
        names.add("Ann");
        names.add("Bo");
        names.remove("Ann");
        System.out.println(names);

        ids.clear();
        System.out.println("Empty: " + ids.isEmpty() + " " + ids);
    }
}

